  1	package com.pousadamarealta;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.PropertyNamingStrategies;
  5	import com.fasterxml.jackson.databind.SerializationFeature;
  6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  7	import com.pousadamarealta.controller.ApiController;
  8	import com.pousadamarealta.domain.repository.MessageRepository;
  9	import com.pousadamarealta.domain.repository.ReservationRepository;
 10	import com.pousadamarealta.domain.repository.RoomRepository;
 11	import com.pousadamarealta.infrastructure.DatabaseInitializer;
 12	import com.pousadamarealta.infrastructure.InMemoryRoomRepository;
 13	import com.pousadamarealta.infrastructure.PostgresMessageRepository;
 14	import com.pousadamarealta.infrastructure.PostgresReservationRepository;
 15	import com.pousadamarealta.messaging.MessageService;
 16	import com.pousadamarealta.service.DocumentService;
 17	import com.pousadamarealta.service.PricingService;
 18	import com.pousadamarealta.service.ReportService;
 19	import com.pousadamarealta.service.ReservationService;
 20	import com.zaxxer.hikari.HikariConfig;
 21	import com.zaxxer.hikari.HikariDataSource;
 22	import io.javalin.Javalin;
 23	import io.javalin.json.JavalinJackson;
 24	
 25	import javax.sql.DataSource;
 26	
 27	public class Application {
 28	
 29	    public static void main(String[] args) {
 30	        int port = getPort();
 31	        boolean isTestMode = isTestMode();
 32	
 33	        DataSource dataSource = createDataSource();
 34	        DatabaseInitializer.initialize(dataSource);
 35	
 36	        RoomRepository roomRepository = new InMemoryRoomRepository();
 37	        ReservationRepository reservationRepository = new PostgresReservationRepository(dataSource);
 38	        MessageRepository messageRepository = new PostgresMessageRepository(dataSource);
 39	
 40	        PricingService pricingService = new PricingService();
 41	        DocumentService documentService = new DocumentService(roomRepository);
 42	        MessageService messageService = new MessageService(messageRepository, isTestMode);
 43	        ReservationService reservationService = new ReservationService(
 44	            reservationRepository, roomRepository, pricingService, documentService, messageService);
 45	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 46	
 47	        ApiController apiController = new ApiController(
 48	            roomRepository, reservationService, messageService, reportService);
 49	
 50	        ObjectMapper objectMapper = new ObjectMapper();
 51	        objectMapper.registerModule(new JavaTimeModule());
 52	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 53	        objectMapper.setPropertyNamingStrategy(PropertyNamingStrategies.LOWER_CAMEL_CASE);
 54	
 55	        Javalin app = Javalin.create(config -> {
 56	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 57	        });
 58	
 59	        apiController.registerRoutes(app);
 60	
 61	        app.start(port);
 62	
 63	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 64	        System.out.println("Servidor iniciado na porta " + port);
 65	        System.out.println("Modo de teste: " + (isTestMode ? "ATIVADO" : "DESATIVADO"));
 66	    }
 67	
 68	    private static int getPort() {
 69	        String portEnv = System.getenv("PORT");
 70	        if (portEnv != null && !portEnv.isEmpty()) {
 71	            return Integer.parseInt(portEnv);
 72	        }
 73	        return 7070;
 74	    }
 75	
 76	    private static boolean isTestMode() {
 77	        String testModeEnv = System.getenv("HOTEL_TEST_MODE");
 78	        return "true".equalsIgnoreCase(testModeEnv);
 79	    }
 80	
 81	    private static DataSource createDataSource() {
 82	        HikariConfig config = new HikariConfig();
 83	        config.setJdbcUrl(System.getenv("DB_URL"));
 84	        config.setUsername(System.getenv("DB_USER"));
 85	        config.setPassword(System.getenv("DB_PASSWORD"));
 86	        config.setMaximumPoolSize(10);
 87	        return new HikariDataSource(config);
 88	    }
 89	}
 90	package com.pousadamarealta.controller;
 91	
 92	import com.pousadamarealta.controller.dto.CreateReservationRequest;
 93	import com.pousadamarealta.controller.dto.ErrorResponse;
 94	import com.pousadamarealta.domain.exception.ApiException;
 95	import com.pousadamarealta.domain.model.*;
 96	import com.pousadamarealta.domain.repository.RoomRepository;
 97	import com.pousadamarealta.messaging.MessageService;
 98	import com.pousadamarealta.service.ReportService;
 99	import com.pousadamarealta.service.ReservationService;
100	import io.javalin.Javalin;
101	import io.javalin.http.Context;
102	
103	import java.time.LocalDate;
104	import java.time.YearMonth;
105	import java.time.format.DateTimeParseException;
106	import java.util.List;
107	
108	public class ApiController {
109	
110	    private final RoomRepository roomRepository;
111	    private final ReservationService reservationService;
112	    private final MessageService messageService;
113	    private final ReportService reportService;
114	
115	    public ApiController(RoomRepository roomRepository,
116	                        ReservationService reservationService,
117	                        MessageService messageService,
118	                        ReportService reportService) {
119	        this.roomRepository = roomRepository;
120	        this.reservationService = reservationService;
121	        this.messageService = messageService;
122	        this.reportService = reportService;
123	    }
124	
125	    public void registerRoutes(Javalin app) {
126	        app.get("/rooms", this::getRooms);
127	        app.post("/reservations", this::createReservation);
128	        app.get("/reservations/{id}", this::getReservation);
129	        app.post("/reservations/{id}/confirmation", this::confirmReservation);
130	        app.post("/reservations/{id}/cancellation", this::cancelReservation);
131	        app.post("/reservations/{id}/check-in", this::checkIn);
132	        app.post("/reservations/{id}/check-out", this::checkOut);
133	        app.get("/reservations/{id}/document", this::getDocument);
134	        app.get("/messages", this::getMessages);
135	        app.get("/reports/occupancy", this::getOccupancyReport);
136	        app.get("/reports/revenue", this::getRevenueReport);
137	
138	        app.exception(ApiException.class, this::handleApiException);
139	        app.exception(Exception.class, this::handleGenericException);
140	    }
141	
142	    private void getRooms(Context ctx) {
143	        List<Room> rooms = roomRepository.findAll();
144	        ctx.json(rooms);
145	    }
146	
147	    private void createReservation(Context ctx) {
148	        try {
149	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
150	
151	            validateRequiredFields(request);
152	
153	            Reservation reservation = new Reservation();
154	            reservation.setRoomNumber(request.getRoomNumber());
155	            reservation.setGuestName(request.getGuestName());
156	            reservation.setGuestEmail(request.getGuestEmail());
157	            reservation.setGuestCpf(request.getGuestCpf());
158	
159	            try {
160	                reservation.setCheckIn(LocalDate.parse(request.getCheckIn()));
161	                reservation.setCheckOut(LocalDate.parse(request.getCheckOut()));
162	            } catch (DateTimeParseException e) {
163	                throw new ApiException("INVALID_REQUEST", "Invalid date format", 400);
164	            }
165	
166	            if (reservation.getCheckOut().isBefore(reservation.getCheckIn()) ||
167	                reservation.getCheckOut().isEqual(reservation.getCheckIn())) {
168	                throw new ApiException("INVALID_REQUEST", "Check-out must be after check-in", 400);
169	            }
170	
171	            reservation.setGuests(request.getGuests());
172	
173	            if (reservation.getGuests() < 1) {
174	                throw new ApiException("INVALID_REQUEST", "At least one guest is required", 400);
175	            }
176	
177	            try {
178	                reservation.setRatePlan(RatePlan.valueOf(request.getRatePlan()));
179	            } catch (IllegalArgumentException e) {
180	                throw new ApiException("INVALID_REQUEST", "Invalid rate plan", 400);
181	            }
182	
183	            Reservation created = reservationService.createReservation(reservation);
184	            ctx.status(201).json(created);
185	
186	        } catch (Exception e) {
187	            if (e instanceof ApiException) {
188	                throw e;
189	            }
190	            throw new ApiException("INVALID_REQUEST", "Invalid request body", 400);
191	        }
192	    }
193	
194	    private void validateRequiredFields(CreateReservationRequest request) {
195	        if (request.getRoomNumber() == null || request.getGuestName() == null ||
196	            request.getGuestEmail() == null || request.getGuestCpf() == null ||
197	            request.getCheckIn() == null || request.getCheckOut() == null ||
198	            request.getGuests() == null || request.getRatePlan() == null) {
199	            throw new ApiException("INVALID_REQUEST", "Missing required fields", 400);
200	        }
201	    }
202	
203	    private void getReservation(Context ctx) {
204	        Long id = Long.parseLong(ctx.pathParam("id"));
205	        Reservation reservation = reservationService.getReservation(id);
206	        ctx.json(reservation);
207	    }
208	
209	    private void confirmReservation(Context ctx) {
210	        Long id = Long.parseLong(ctx.pathParam("id"));
211	        Reservation reservation = reservationService.confirmReservation(id);
212	        ctx.json(reservation);
213	    }
214	
215	    private void cancelReservation(Context ctx) {
216	        Long id = Long.parseLong(ctx.pathParam("id"));
217	        Reservation reservation = reservationService.cancelReservation(id);
218	        ctx.json(reservation);
219	    }
220	
221	    private void checkIn(Context ctx) {
222	        Long id = Long.parseLong(ctx.pathParam("id"));
223	        Reservation reservation = reservationService.checkIn(id);
224	        ctx.json(reservation);
225	    }
226	
227	    private void checkOut(Context ctx) {
228	        Long id = Long.parseLong(ctx.pathParam("id"));
229	        Reservation reservation = reservationService.checkOut(id);
230	        Document document = reservationService.getDocument(id);
231	        ctx.json(document);
232	    }
233	
234	    private void getDocument(Context ctx) {
235	        Long id = Long.parseLong(ctx.pathParam("id"));
236	        Document document = reservationService.getDocument(id);
237	        ctx.json(document);
238	    }
239	
240	    private void getMessages(Context ctx) {
241	        List<Message> messages = messageService.getAllMessages();
242	        ctx.json(messages);
243	    }
244	
245	    private void getOccupancyReport(Context ctx) {
246	        String dateParam = ctx.queryParam("date");
247	        if (dateParam == null) {
248	            throw new ApiException("INVALID_REQUEST", "Missing date parameter", 400);
249	        }
250	
251	        try {
252	            LocalDate date = LocalDate.parse(dateParam);
253	            String csv = reportService.generateOccupancyReport(date);
254	            ctx.contentType("text/csv; charset=utf-8").result(csv);
255	        } catch (DateTimeParseException e) {
256	            throw new ApiException("INVALID_REQUEST", "Invalid date format", 400);
257	        }
258	    }
259	
260	    private void getRevenueReport(Context ctx) {
261	        String monthParam = ctx.queryParam("month");
262	        if (monthParam == null) {
263	            throw new ApiException("INVALID_REQUEST", "Missing month parameter", 400);
264	        }
265	
266	        try {
267	            YearMonth yearMonth = YearMonth.parse(monthParam);
268	            String csv = reportService.generateRevenueReport(
269	                yearMonth.getYear(), yearMonth.getMonthValue());
270	            ctx.contentType("text/csv; charset=utf-8").result(csv);
271	        } catch (DateTimeParseException e) {
272	            throw new ApiException("INVALID_REQUEST", "Invalid month format", 400);
273	        }
274	    }
275	
276	    private void handleApiException(ApiException e, Context ctx) {
277	        ctx.status(e.getStatusCode())
278	           .json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
279	    }
280	
281	    private void handleGenericException(Exception e, Context ctx) {
282	        e.printStackTrace();
283	        ctx.status(500)
284	           .json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
285	    }
286	}

