 15	import com.pousadamarealta.messaging.rules.TestModeRule;
 16	
 17	import java.util.ArrayList;
 18	import java.util.List;
 19	
 20	public class MessageService {
 21	
 22	    private final MessageRepository messageRepository;
 23	    private final List<MessageProcessor> processors;
 24	    private final ProcessingContext context;
 25	
