 10	import java.time.format.DateTimeFormatter;
 11	import java.util.Locale;
 12	
 13	public class DocumentService {
 14	
 15	    private final RoomRepository roomRepository;
 16	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
 17	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 18	
 19	    public DocumentService(RoomRepository roomRepository) {
 20	        this.roomRepository = roomRepository;
 21	    }
 22	
 23	    public Document generateDocument(Reservation reservation) {
 24	        Document doc = new Document();
 25	        doc.setReservationId(reservation.getId());
 26	        doc.setGuestName(reservation.getGuestName());
 27	        doc.setGuestCpf(reservation.getGuestCpf());
 28	        doc.setRoomNumber(reservation.getRoomNumber());
 29	
 30	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
 31	            .orElseThrow(() -> new RuntimeException("Room not found"));
 32	        doc.setRoomType(room.getType());
 33	
 34	        doc.setCheckIn(reservation.getCheckIn());
 35	        doc.setCheckOut(reservation.getCheckOut());
 36	        doc.setNights(reservation.getNights());
 37	        doc.setSubtotal(reservation.getSubtotal());
 38	        doc.setDiscount(reservation.getDiscount());
 39	        doc.setTotal(reservation.getTotal());
 40	
 41	        return doc;
 42	    }
 43	
 44	    public String formatDocument(Document doc) {
 45	        StringBuilder sb = new StringBuilder();
 46	        sb.append("Comprovante de reserva nº ").append(doc.getReservationId()).append("\n");
 47	        sb.append("Hóspede: ").append(doc.getGuestName());
 48	        sb.append(" (CPF ").append(formatCpf(doc.getGuestCpf())).append(")\n");
 49	        sb.append("Quarto: ").append(doc.getRoomNumber());
 50	        sb.append(" (").append(doc.getRoomType()).append(")\n");
 51	        sb.append("Entrada: ").append(doc.getCheckIn().format(DATE_FORMAT));
 52	        sb.append(" | Saída: ").append(doc.getCheckOut().format(DATE_FORMAT));
 53	        sb.append(" | ").append(doc.getNights());
 54	        sb.append(doc.getNights() == 1 ? " diária" : " diárias").append("\n");
 55	        sb.append("Diárias: ").append(formatCurrency(doc.getSubtotal())).append("\n");
 56	
 57	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
 58	            sb.append("Desconto: ").append(formatCurrency(doc.getDiscount())).append("\n");
 59	        }
 60	
 61	        sb.append("Total: ").append(formatCurrency(doc.getTotal()));
 62	
 63	        return sb.toString();
 64	    }
 65	
 66	    public String createConfirmationEmail(Reservation reservation, String documentText) {
 67	        StringBuilder sb = new StringBuilder();
 68	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
 69	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
 70	        sb.append(documentText).append("\n\n");
 71	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
 72	        sb.append("Até breve!");
 73	
 74	        return sb.toString();
 75	    }
 76	
 77	    private String formatCpf(String cpf) {
 78	        if (cpf.length() == 11) {
 79	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
 80	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
 81	        }
 82	        return cpf;
 83	    }
 84	
 85	    private String formatCurrency(BigDecimal value) {
 86	        return CURRENCY_FORMAT.format(value);
 87	    }
 88	}
 89	package com.pousadamarealta.service;
 90	
 91	import com.pousadamarealta.domain.model.RatePlan;
 92	import com.pousadamarealta.domain.model.Room;
 93	
 94	import java.math.BigDecimal;
 95	import java.math.RoundingMode;
 96	import java.time.LocalDate;
 97	import java.time.temporal.ChronoUnit;
 98	
 99	public class PricingService {
100	
101	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
102	
103	    public int calculateNights(LocalDate checkIn, LocalDate checkOut) {
104	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
105	    }
106	
107	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
108	        BigDecimal subtotal = BigDecimal.ZERO;
109	        LocalDate currentDate = checkIn;
110	
111	        while (currentDate.isBefore(checkOut)) {
112	            BigDecimal nightlyRate = room.getNightlyRate();
113	            if (isHighSeason(currentDate)) {
114	                nightlyRate = nightlyRate.multiply(HIGH_SEASON_MULTIPLIER);
115	            }
116	            nightlyRate = round(nightlyRate);
117	            subtotal = subtotal.add(nightlyRate);
118	            currentDate = currentDate.plusDays(1);
119	        }
120	
121	        return round(subtotal);
122	    }
123	
124	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
125	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate());
126	        return round(discount);
127	    }
128	
129	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
130	        return round(subtotal.subtract(discount));
131	    }
132	
133	    private boolean isHighSeason(LocalDate date) {
134	        int month = date.getMonthValue();
135	        int day = date.getDayOfMonth();
136	
137	        if (month == 7) {
138	            return true;
139	        }
140	
141	        if (month == 12 && day >= 15) {
142	            return true;
143	        }
144	
145	        if (month == 1 || month == 2) {
146	            return true;
147	        }
148	
149	        return false;
150	    }
151	
152	    private BigDecimal round(BigDecimal value) {
153	        return value.setScale(2, RoundingMode.HALF_EVEN);
154	    }
155	}
