192	            csv.append(r.getCheckOut().format(DATE_FORMAT)).append("\n");
193	        }
194	
195	        csv.append("total,").append(reservations.size()).append("/").append(allRooms.size());
196	
197	        return csv.toString();
198	    }
199	
200	    public String generateRevenueReport(int year, int month) {
201	        List<Reservation> reservations = reservationRepository.findReservationsStartingInMonth(year, month);
202	
203	        StringBuilder csv = new StringBuilder();
204	        csv.append("reservation,room,check_in,check_out,status,amount\n");
205	
206	        BigDecimal total = BigDecimal.ZERO;
207	
208	        for (Reservation r : reservations) {
209	            BigDecimal revenue = r.getAmountPaid().subtract(
210	                r.getRefund() != null ? r.getRefund() : BigDecimal.ZERO
211	            );
212	
213	            csv.append(r.getId()).append(",");
214	            csv.append(r.getRoomNumber()).append(",");
215	            csv.append(r.getCheckIn().format(DATE_FORMAT)).append(",");
216	            csv.append(r.getCheckOut().format(DATE_FORMAT)).append(",");
217	            csv.append(r.getStatus()).append(",");
218	            csv.append(formatDecimal(revenue)).append("\n");
219	
220	            total = total.add(revenue);
221	        }
222	
223	        csv.append("total,").append(formatDecimal(total));
224	
225	        return csv.toString();
226	    }
227	
228	    private String formatDecimal(BigDecimal value) {
229	        return value.toString();
230	    }
231	}
