 98	    public PostgresMessageRepository(DataSource dataSource) {
 99	        this.dataSource = dataSource;
100	    }
101	
102	    @Override
103	    public Message save(Message message) {
104	        String sql = """
105	            INSERT INTO messages (channel, recipient, subject, body, status)
106	            VALUES (?, ?, ?, ?, ?)
107	            """;
108	
109	        try (Connection conn = dataSource.getConnection();
110	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
111	
112	            stmt.setString(1, message.getChannel().name());
113	            stmt.setString(2, message.getTo());
114	            stmt.setString(3, message.getSubject());
115	            stmt.setString(4, message.getBody());
116	            stmt.setString(5, message.getStatus().name());
117	
118	            stmt.executeUpdate();
119	
120	            try (ResultSet keys = stmt.getGeneratedKeys()) {
121	                if (keys.next()) {
122	                    message.setId(keys.getLong(1));
123	                }
124	            }
125	
126	            return message;
127	        } catch (SQLException e) {
128	            throw new RuntimeException("Failed to save message", e);
129	        }
130	    }
131	
132	    @Override
133	    public List<Message> findAll() {
134	        String sql = "SELECT * FROM messages ORDER BY id";
135	
136	        try (Connection conn = dataSource.getConnection();
137	             PreparedStatement stmt = conn.prepareStatement(sql);
138	             ResultSet rs = stmt.executeQuery()) {
139	
140	            List<Message> messages = new ArrayList<>();
141	            while (rs.next()) {
142	                messages.add(mapMessage(rs));
